mapper.select:
select id
from chat_conversations
where conversation_type = 'direct'
  and direct_user_one_id = #{firstUserId}
  and direct_user_two_id = #{secondUserId}

select c.id, c.conversation_type, c.name, c.owner_user_id, c.conversation_state, c.dissolved_at, c.updated_at, coalesce(c.last_message_at, c.created_at) as activity_at, case when c.conversation_type = 'group' then c.name else ( select peer_user.nickname from chat_conversation_members peer join users peer_user on peer_user.id = peer.user_id where peer.conversation_id = c.id and peer.member_state = 'active' and peer.user_id <> #{userId} ) end as display_name, case when c.conversation_type = 'direct' then ( select peer_user.avatar_url from chat_conversation_members peer join users peer_user on peer_user.id = peer.user_id where peer.conversation_id = c.id and peer.member_state = 'active' and peer.user_id <> #{userId} ) else null end as display_avatar_url, lm.id as message_id, lm.conversation_id as message_conversation_id, lm.sender_user_id as message_sender_user_id, message_sender.nickname as message_sender_nickname, message_sender.avatar_url as message_sender_avatar_url, lm.message_type as message_message_type, lm.body as message_body, lm.shared_content_id as message_shared_content_id, message_content.title as message_shared_content_title, message_content.cover_url as message_shared_content_cover_url, message_content.author_user_id as message_shared_content_author_user_id, message_author.nickname as message_shared_content_author_nickname, lm.client_message_id as message_client_message_id, lm.created_at as message_created_at, ( select count(*) from chat_messages unread where unread.conversation_id = c.id and unread.sequence_no > membership.last_read_message_sequence and unread.sender_user_id <> #{userId} ) as unread_count from chat_conversation_members membership join chat_conversations c on c.id = membership.conversation_id left join chat_messages lm on lm.id = c.last_message_id left join users message_sender on message_sender.id = lm.sender_user_id left join content_items message_content on message_content.id = lm.shared_content_id and lm.message_type = 'video_share' left join users message_author on message_author.id = message_content.author_user_id where membership.user_id = #{userId} and membership.member_state = 'active'
and ( coalesce(c.last_message_at, c.created_at) < #{cursorAt} or ( coalesce(c.last_message_at, c.created_at) = #{cursorAt} and c.id < #{cursorId} ) )
order by coalesce(c.last_message_at, c.created_at) desc, c.id desc limit #{limit}

select ranked.conversation_id, ranked.user_id, ranked.nickname, ranked.avatar_url from ( select membership.conversation_id, membership.user_id, member_user.nickname, member_user.avatar_url, row_number() over ( partition by membership.conversation_id order by case when membership.user_id = conversation.owner_user_id then 0 else 1 end, membership.joined_at, membership.user_id ) as member_order from chat_conversation_members membership join chat_conversations conversation on conversation.id = membership.conversation_id join users member_user on member_user.id = membership.user_id where membership.member_state = 'active' and conversation.conversation_type = 'group' and membership.conversation_id in
#{conversationId}
) ranked where ranked.member_order <= 4 order by ranked.conversation_id, ranked.member_order

mapper.update:
update chat_conversations
set name = #{name}, updated_at = current_timestamp
where id = #{conversationId}

update chat_conversation_members set member_role = case when user_id = #{previousOwnerUserId} then 'member' else 'owner' end where conversation_id = #{conversationId} and user_id in
#{userId}
and member_state = 'active'

update chat_conversations
set owner_user_id = #{ownerUserId}, updated_at = current_timestamp
where id = #{conversationId}

update chat_conversation_members
set member_state = 'removed', left_at = current_timestamp
where conversation_id = #{conversationId}
  and user_id = #{userId}

update chat_conversation_members
set member_state = 'left', left_at = current_timestamp
where conversation_id = #{conversationId}
  and user_id = #{userId}
  and member_state = 'active'

mapper.select:
select

from chat_messages message
join users sender on sender.id = message.sender_user_id
left join content_items shared_content
  on shared_content.id = message.shared_content_id
 and message.message_type = 'video_share'
left join users shared_author
  on shared_author.id = shared_content.author_user_id
where message.conversation_id = #{conversationId}

  and (
      message.sequence_no < #{cursorSequence}
      or (
          message.sequence_no = #{cursorSequence}
          and message.id < #{cursorId}
      )
  )

order by message.sequence_no desc, message.id desc
limit #{limit}

